/* ========= الدروس والشروحات (مأخوذة من كتاب الكفاية النحوية) ========= */
const LESSONS = [
  { id: 'atf', g: 't', n: 'العطف', info: `
    <p>اسم أو فعل مسبوق بحرف عطف، يتبع ما قبله في الإعراب.</p>
    <p><b>أركانه:</b> معطوف عليه + حرف عطف + معطوف.</p>
    <p><b>حروف العطف:</b> الواو، الفاء، ثم، أو، أم، حتى، لكنْ، لا، بل.</p>` },
  { id: 'nat', g: 't', n: 'النعت (الصفة)', info: `
    <p>اسم يبيّن صفة ما قبله (المنعوت)، ويتبعه في الإعراب.</p>
    <p><b>مثال:</b> جاء الطالبُ <em>المجتهدُ</em> — المجتهدُ: نعت مرفوع وعلامة رفعه الضمة.</p>` },
  { id: 'twk', g: 't', n: 'التوكيد', info: `
    <p>التوكيد نوعان:</p>
    <p><b>لفظي:</b> تكرار الكلمة أو الجملة. مثل: ظهرَ الحقُّ، ظهرَ الحقُّ.</p>
    <p><b>معنوي:</b> من ألفاظه: نفس، عين، كلا، كلتا، كل، جميع، عامة. مثل: حضرَ الضيوفُ <em>كلُّهم</em>.</p>` },
  { id: 'bdl', g: 't', n: 'البدل', info: `
    <p>البدل ثلاثة أنواع:</p>
    <p><b>بدل كل من كل:</b> البدل = المبدل منه. مثل: جاء الأستاذُ محمدٌ.</p>
    <p><b>بدل بعض من كل:</b> البدل جزء من المبدل منه. مثل: عالجَ الطبيبُ المريضَ رأسَه.</p>
    <p><b>بدل اشتمال:</b> البدل ينتمي إلى المبدل منه. مثل: أعجبني زيدٌ خلقُه.</p>` },
  { id: 'nda', g: 'a', n: 'النداء', info: `
    <p><b>حروف النداء:</b> يا، أ، أي، أيا، هيا.</p>
    <p><b>المنادى كلمة واحدة:</b> إما مبني على ما يرفع به (العلم المفرد، النكرة المقصودة، المعرّف بـ«ال»)، وإما منصوب (النكرة غير المقصودة).</p>
    <p><b>المنادى كلمتان:</b> منصوب، وله نوعان: المضاف، وشبيه بالمضاف.</p>` },
  { id: 'ist', g: 'a', n: 'الاستثناء', info: `
    <p>ثلاثة أنواع:</p>
    <p><b>تام مثبت:</b> حفظتُ القصيدةَ إلا بيتين. (المستثنى منصوب)</p>
    <p><b>تام منفي:</b> ما غابَ أحدٌ إلا محمدًا / محمدٌ. (النصب أو الإتباع)</p>
    <p><b>ناقص منفي (مفرّغ):</b> ما غابَ إلا محمدٌ. (يُعرب حسب موقعه)</p>
    <p class="tip">احذف «إلا» وما بعدها لتعرف هل الكلام تام أم ناقص.</p>` },
  { id: 'tjb', g: 'a', n: 'التعجب', info: `
    <p><b>الصيغة الغالبة:</b> ما التعجبية + فعل على وزن «أفعلَ» + اسم منصوب (المتعجب منه) + علامة التعجب (!).</p>
    <p><b>أمثلة:</b> ما أجملَ الهدوءَ! · ما أطولَ السفرَ! · ما أقبحَ الكذبَ!</p>
    <p class="tip">صيغة «أفعل» والمتعجب منه كلاهما منصوبان.</p>` },
  { id: 'adad', g: 'a', n: 'العدد', info: `
    <p><b>التمييز:</b> الأعداد من 3 إلى 10: جمع مجرور · من 11 إلى 99: مفرد منصوب · المئة والألف: مفرد مجرور.</p>
    <p><b>المطابقة:</b> العددان 1 و2 يوافقان المعدود في التذكير والتأنيث. الأعداد من 3 إلى 9 تخالف المعدود. العشرة المفردة تخالف المعدود، والعشر المركبة توافقه.</p>` }
];

