/* ===== gen-adad.js ===== */
/* مولّد أسئلة العدد: حتمي (نفس الأسئلة في كل مرة)، وجميع الجمل صحيحة نحويًا */
const GEN_ADAD = (() => {
  // [مفرد مجرور، مفرد منصوب، جمع مجرور، جمع منصوب، الجنس]
  const N = [['كتابٍ','كتابًا','كتبٍ','كتبًا','m'],['قلمٍ','قلمًا','أقلامٍ','أقلامًا','m'],['طالبٍ','طالبًا','طلابٍ','طلابًا','m'],['بابٍ','بابًا','أبوابٍ','أبوابًا','m'],['درسٍ','درسًا','دروسٍ','دروسًا','m'],['ولدٍ','ولدًا','أولادٍ','أولادًا','m'],
    ['مدينةٍ','مدينةً','مدنٍ','مدنًا','f'],['شجرةٍ','شجرةً','أشجارٍ','أشجارًا','f'],['قصةٍ','قصةً','قصصٍ','قصصًا','f'],['ورقةٍ','ورقةً','أوراقٍ','أوراقًا','f'],['غرفةٍ','غرفةً','غرفٍ','غرفًا','f'],['فكرةٍ','فكرةً','أفكارٍ','أفكارًا','f']];
  const T = ['ثلاثةَ','أربعةَ','خمسةَ','ستةَ','سبعةَ','ثمانيةَ','تسعةَ','عشرةَ'], F = ['ثلاثَ','أربعَ','خمسَ','ستَّ','سبعَ','ثمانيَ','تسعَ','عشرَ'];
  const M11 = ['أحدَ عشرَ','ثلاثةَ عشرَ','أربعةَ عشرَ','خمسةَ عشرَ','ستةَ عشرَ','سبعةَ عشرَ','ثمانيةَ عشرَ','تسعةَ عشرَ'];
  const F11 = ['إحدى عشرةَ','ثلاثَ عشرةَ','أربعَ عشرةَ','خمسَ عشرةَ','ستَّ عشرةَ','سبعَ عشرةَ','ثمانيَ عشرةَ','تسعَ عشرةَ'];
  const TN = ['عشرينَ','ثلاثينَ','أربعينَ','خمسينَ','ستينَ','سبعينَ','ثمانينَ','تسعينَ'];
  const V = ['رأيتُ','وجدتُ','عددتُ','أحضرتُ','لاحظتُ','جمعتُ'];
  const out = []; let c = 0;
  const mk = (k, q, ok, bad, e) => out.push({ l: 'adad', k, t: 'mcq', d: 2, q: `${V[c++ % V.length]} ${q}`, o: [ok, ...bad], a: 0, e });
  for (let n = 0; n < 8; n++) for (let j = 0; j < 4; j++) { const x = N[(n * 3 + j * 5) % 12]; mk('تمييز العدد', `${(x[4] === 'm' ? T : F)[n]} ______`, x[2], [x[3], x[0], x[1]], 'تمييز الأعداد من 3 إلى 10 جمع مجرور.'); }
  for (let n = 0; n < 8; n++) for (let j = 0; j < 3; j++) { const x = N[(n * 5 + j * 4) % 12]; mk('تمييز العدد', `${(x[4] === 'm' ? M11 : F11)[n]} ______`, x[1], [x[0], x[2], x[3]], 'تمييز الأعداد من 11 إلى 99 مفرد منصوب.'); }
  for (let n = 0; n < 8; n++) for (let j = 0; j < 2; j++) { const x = N[(n * 7 + j * 6) % 12]; mk('تمييز العدد', `${TN[n]} ______`, x[1], [x[0], x[2], x[3]], 'تمييز الأعداد من 11 إلى 99 مفرد منصوب.'); }
  ['مئةَ', 'ألفَ'].forEach((w, m) => { for (let k = 0; k < 6; k++) { const x = N[(k * 2 + m) % 12]; mk('تمييز العدد', `${w} ______`, x[0], [x[1], x[2], x[3]], 'تمييز المئة والألف مفرد مجرور.'); } });
  for (let n = 0; n < 8; n++) for (let j = 0; j < 2; j++) { const x = N[(n * 5 + j * 7 + 1) % 12], m = x[4] === 'm'; mk('مطابقة العدد للمعدود', `______ ${x[2]}  (اختاري العدد المناسب)`, (m ? T : F)[n], [(m ? F : T)[n]], 'العدد من 3 إلى 10 يخالف المعدود في التذكير والتأنيث.'); }
  return out;
})();

