const sshuf = (a, s) => { a = [...a]; for (let i = a.length; i > 1;) { s = s * 16807 % 2147483647; const j = s % i--; [a[i], a[j]] = [a[j], a[i]]; } return a; };
const PN = { 5: 10, 10: 20, 15: 30 };
const P = (() => {
  const P = { 5: [], 10: [], 15: [], g: [] };
  LESSONS.forEach(l => {
    const L = sshuf(ALL.filter(q => q.l === l.id), 7);
    if (L.length >= 80) { let o = 0; [5, 10, 15].forEach(n => { P[n].push(...L.slice(o, o + PN[n])); o += PN[n]; }); P.g.push(...L.slice(o)); }
    else [5, 10, 15, 'g'].forEach(n => P[n].push(...L));
  });
  return P;
})();
const pl = () => (mode === 'exam' ? P[len] : P.g).filter(q => sel.has(q.l));
const rec = (q, ok) => { const a = store.get('sk', {}), k = q.l + '|' + q.k, x = a[k] ?? [0, 0]; a[k] = [x[0] + ok, x[1] + 1]; store.set('sk', a); };

let sel = new Set(LESSONS.map(l => l.id)), mode = 'exam', len = 10, Q = [], i = 0, locked = false;

/* ---------- المظهر (غامق / نهاري) ---------- */
const root = document.documentElement;
function theme(t) {
  root.dataset.theme = t; store.set('th', t);
  $('#tg').textContent = t === 'dark' ? 'الوضع النهاري' : 'الوضع الليلي';
}
$('#tg').onclick = () => theme(root.dataset.theme === 'dark' ? 'light' : 'dark');
theme(store.get('th', 'dark'));

/* ---------- التنقل ---------- */
let scrollOff = null;
const V = { home, quizzes: () => setup('exam'), train: () => setup('practice'), learn, games, knowledge, skills };
function go(v) {
  if (scrollOff) scrollOff(); scrollOff = null;
  app.className = v === 'home' ? 'home' : '';
  document.querySelectorAll('nav [data-go]').forEach(b => b.classList.toggle('on', b.dataset.go === (v === 'learn' || v === 'train' ? 'games' : v)));
  V[v]();
  window.scrollTo(0, 0);
}
const bindGo = r => r.querySelectorAll('[data-go]').forEach(b => b.onclick = () => go(b.dataset.go));
bindGo(document);

const avail = () => pl().length;
const chipsHTML = () => ['t', 'a'].map(g => `<div class="grp">${g === 't' ? 'التوابع' : 'الأساليب النحوية'}</div><div class="chips">
  ${LESSONS.filter(l => l.g === g).map(l => `<button class="chip${sel.has(l.id) ? ' on' : ''}" data-l="${l.id}" aria-pressed="${sel.has(l.id)}">${l.n}</button>`).join('')}</div>`).join('') +
  `<div class="row"><button class="btn ghost" id="all">تحديد الكل</button><button class="btn ghost" id="none">إلغاء التحديد</button></div>`;
function bindChips(re) {
  app.querySelectorAll('[data-l]').forEach(b => b.onclick = () => { const k = b.dataset.l; sel.has(k) ? sel.delete(k) : sel.add(k); re(); });
  $('#all').onclick = () => { sel = new Set(LESSONS.map(l => l.id)); re(); };
  $('#none').onclick = () => { sel.clear(); re(); };
}

/* ---------- الرئيسية ---------- */
// اليد التي تكون في الأعلى ومقلوبة: 'robot' أو 'human' (جرّبي الاثنين)
const HANDS_TOP = 'robot';
function home() {
  const sec = [['quizzes', '1', 'الاختبارات', 'من 5 إلى 15 سؤالًا عشوائيًا، وتحليل لمهاراتك في النهاية.'],
    ['games', '2', 'الألعاب والتدريبات', 'تدريب فوري وتحديات ممتعة وشروحات مفصلة على كل الدروس.'],
    ['knowledge', '3', 'المعارف', 'قصة كل درس والعلماء الذين وضعوا قواعده.']];
  app.innerHTML = `
  <section class="stage" id="stage"><div class="sticky">
    <div class="intro" id="it"><span class="kick">مشروع الكفاية اللغوية</span>
      <h1>النحو العربي،<br>بنظرة جديدة</h1>
      <p class="sub">منصة تفاعلية لطالبات الثانوي لإتقان التوابع والأساليب النحوية: شرح وتدريب وألعاب واختبارات تكشف مهاراتك.</p></div>
    <div class="hands ${HANDS_TOP === 'robot' ? 'rt' : 'ht'}">
      <img id="hr" alt="" src="images/hand-robot.png" onerror="this.onerror=null;this.src='images/hand-robot.svg'">
      <img id="hh" alt="" src="images/hand-human.png" onerror="this.onerror=null;this.src='images/hand-human.svg'"></div>
    <div class="aw"><div class="about" id="ab"><h2>عن هذا المشروع</h2>
      <p>يهدف الموقع إلى تبسيط التوابع (العطف، والنعت، والتوكيد، والبدل) والأساليب النحوية (النداء، والاستثناء، والتعجب، والعدد) وفق مقرر الكفاية النحوية، وتحويلها إلى تجربة تعلّم تقيس مهارتك وتخبرك أين تحتاجين إلى مزيد من التدريب.</p>
      <p>وتنسجم فكرته مع توجّه ربط مشروعات الكفاية بالذكاء الاصطناعي، فقد بُني بمساعدته في التصميم والبرمجة وصياغة الأسئلة. ولهذا تلتقي في الصورة يد بشرية بيد آلية: المعرفة إنسانية، والذكاء الاصطناعي عون لها.</p></div></div>
  </div></section>
  <div class="wrap"><h2 class="ttl">اختاري وجهتك</h2><div class="secs">
    ${sec.map(s => `<button class="sec" data-go="${s[0]}"><span class="no">${s[1]}</span><span class="st">${s[2]}</span><span class="ds">${s[3]}</span><span class="ar">←</span></button>`).join('')}</div></div>`;
  bindGo(app); hands();
}
function hands() {
  const st = $('#stage'), hr = $('#hr'), hh = $('#hh'), ab = $('#ab'), it = $('#it');
  const still = matchMedia('(prefers-reduced-motion: reduce)').matches;
  if (still) st.classList.add('still');
  const c = x => Math.min(1, Math.max(0, x)), ez = t => t < .5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
  const rt = HANDS_TOP === 'robot';
  let a = still ? 1 : 0, raf, t0;
  const draw = () => {
    const r = st.getBoundingClientRect(), s = still ? 0 : c(-r.top / (r.height - innerHeight));
    const d = Math.max(1 - ez(a), ez(s)), x = 62 * d, y = 16 * d * d;     // 0 = تلامس · 1 = ابتعاد كامل
    hr.style.transform = `translate(${-x}vw,${rt ? -y : y}vh) rotate(${(rt ? -1 : 1) * -5 * d}deg)${rt ? ' scaleY(-1)' : ''}`;
    hh.style.transform = `translate(${x}vw,${rt ? y : -y}vh) rotate(${(rt ? 1 : -1) * 5 * d}deg)${rt ? '' : ' scaleY(-1)'}`;
    const t = still ? 1 : c((s - .4) / .35);
    it.style.opacity = still ? 1 : 1 - c(s * 1.8);
    ab.style.opacity = t; ab.style.transform = `translateY(${(1 - t) * 24}px)`;
  };
  const loop = ts => { t0 ??= ts; a = c((ts - t0) / 2400); draw(); if (a < 1) raf = requestAnimationFrame(loop); };
  draw(); if (!still) raf = requestAnimationFrame(loop);
  addEventListener('scroll', draw, { passive: true }); addEventListener('resize', draw);
  scrollOff = () => { cancelAnimationFrame(raf); removeEventListener('scroll', draw); removeEventListener('resize', draw); };
}

/* ---------- صفحة الاختبارات / التدريبات ---------- */
function setup(m) {
  mode = m; const ex = m === 'exam', n = avail();
  app.innerHTML = `<div class="hero sm"><span class="kick">${ex ? 'قسم الاختبارات' : 'الألعاب · تدريب فوري'}</span>
    <h1>${ex ? 'اختبري نفسك' : 'تدرّبي بتصحيح فوري'}</h1>
    <p>${ex ? 'أسئلة عشوائية بدون تصحيح أثناء الحل، وتظهر نتيجتك وتحليل مهاراتك في النهاية.' : 'تعرفين صحة إجابتك بعد كل سؤال، لتتعلمي من الخطأ في حينه.'}</p></div>
  <section class="card"><h2>الدروس</h2>${chipsHTML()}</section>
  <section class="card"><h2>عدد الأسئلة</h2>
    <div class="chips">${[5, 10, 15].map(x => `<button class="chip${len === x ? ' on' : ''}" data-n="${x}">${x}</button>`).join('')}</div>
    <p class="note">الأسئلة المتاحة للدروس المختارة: ${n}${n < len && n ? ' — سيظهر المتاح منها.' : ''}</p>
    <div class="row"><button class="btn" id="go" ${n ? '' : 'disabled'}>ابدئي</button></div></section>
  ${ex ? '' : `<section class="card"><h2>الشروحات المفصلة</h2><p>راجعي القاعدة قبل التدريب أو أثناءه.</p><div class="row"><button class="btn ghost" id="rd">افتحي الشروحات</button></div></section>`}`;
  bindChips(() => setup(m));
  app.querySelectorAll('[data-n]').forEach(b => b.onclick = () => { len = +b.dataset.n; setup(m); });
  $('#go').onclick = start;
  if ($('#rd')) $('#rd').onclick = () => go('learn');
}

/* ---------- الشروحات المفصلة ---------- */
function learn() {
  const ls = LESSONS.filter(l => sel.has(l.id));
  app.innerHTML = `<div class="hero sm"><span class="kick">الألعاب</span><h1>الشروحات المفصلة</h1><p>اختاري الدروس التي تريدين قراءتها.</p></div>
    <section class="card">${chipsHTML()}</section>` +
    (ls.length ? ls.map(l => `<section class="card lesson"><h2>${l.n}</h2>${l.info}</section>`).join('') + `<div class="row"><button class="btn" id="st">تدرّبي على هذه الدروس</button></div>` : `<p class="note">لم تختاري أي درس بعد.</p>`);
  bindChips(learn);
  if ($('#st')) $('#st').onclick = () => setup('practice');
}

/* ---------- الألعاب (تشمل التدريب الفوري) ---------- */
function games() {
  const g = [['train', 'تدريب فوري', 'تصحيح فوري بعد كل سؤال مع تعليل الإجابة.'], ['time', 'تحدي الدقيقة', 'أجيبي عن أكبر عدد من الأسئلة قبل انتهاء 60 ثانية.'], ['life', 'سلسلة الأرواح', 'لديك ثلاث أرواح، وكل خطأ يُنقص روحًا. كم تصمدين؟'], ['learn', 'الشروحات المفصلة', 'راجعي القاعدة قبل اللعب أو أثناءه.']];
  app.innerHTML = `<div class="hero sm"><span class="kick">قسم</span><h1>الألعاب والتدريبات</h1><p>اختاري الدروس ثم العبي.</p></div>
  <section class="card"><h2>الدروس</h2>${chipsHTML()}</section>
  <div class="secs">${g.map((x, n) => `<button class="sec" data-g="${x[0]}"><span class="no">${n + 1}</span><span class="st">${x[1]}</span><span class="ds">${x[2]}</span><span class="ar">←</span></button>`).join('')}</div>`;
  bindChips(games);
  app.querySelectorAll('[data-g]').forEach(b => b.onclick = () => ['time', 'life'].includes(b.dataset.g) ? (P.g.some(q => q.t === 'mcq' && sel.has(q.l)) ? arcade(b.dataset.g) : alert('اختاري درسًا واحدًا على الأقل.')) : go(b.dataset.g));
}
function arcade(kind) {
  const pool = shuf(P.g.filter(q => q.t === 'mcq' && sel.has(q.l)));
  let n = 0, ok = 0, lives = 3, t = 60, busy = false, tm = null;
  const end = () => {
    clearInterval(tm); scrollOff = null;
    app.innerHTML = `<section class="card"><h2>انتهت الجولة</h2><div class="score">${ok}</div><p>عدد إجاباتك الصحيحة، وقد أُضيفت نتائجك إلى «مهاراتي».</p><div class="row"><button class="btn" id="ag">العبي مجددًا</button><button class="btn ghost" id="bk">الألعاب</button></div></section>`;
    $('#ag').onclick = () => arcade(kind); $('#bk').onclick = () => go('games');
  };
  const ask = () => {
    if (n >= pool.length) return end();
    const q = pool[n++], or = shuf(q.o.map((_, k) => k)); busy = false;
    app.innerHTML = `<section class="card"><div class="bar"><span>${kind === 'time' ? 'الوقت: <b id="tt">' + t + '</b>' : 'الأرواح: ' + '♥'.repeat(lives)}</span><span>الصحيح: ${ok}</span></div>
      <p class="q">${q.q}</p>${or.map(k => `<button class="opt" data-k="${k}">${q.o[k]}</button>`).join('')}<div class="row"><button class="btn ghost" id="qt">خروج</button></div></section>`;
    app.querySelectorAll('.opt').forEach(b => b.onclick = () => {
      if (busy) return; busy = true;
      const good = +b.dataset.k === q.a; rec(q, +good);
      if (good) ok++; else if (kind === 'life') lives--;
      app.querySelectorAll('.opt').forEach(x => x.classList.add(+x.dataset.k === q.a ? 'right' : x === b ? 'wrong' : 'dim'));
      setTimeout(() => lives > 0 && t > 0 ? ask() : end(), good ? 600 : 1300);
    });
    $('#qt').onclick = () => go('games');
  };
  if (kind === 'time') tm = setInterval(() => { t--; const e = $('#tt'); if (e) e.textContent = Math.max(t, 0); if (t <= 0) { clearInterval(tm); if (!busy) end(); } }, 1000);
  scrollOff = () => clearInterval(tm);
  ask();
}

/* ---------- المعارف ---------- */
let kl = 'atf';
function knowledge() {
  if (typeof KNOWLEDGE === 'undefined') { app.innerHTML = '<section class="card"><p>ملف knowledge.js غير موجود في مجلد الموقع.</p></section>'; return; }
  const k = KNOWLEDGE[kl];
  app.innerHTML = `<div class="hero sm"><span class="kick">قسم</span><h1>المعارف</h1><p>لكل درس قصته، والعلماء الذين نسّقوه ووضعوا قواعده.</p></div>
  <section class="card"><div class="chips">${LESSONS.map(l => `<button class="chip${kl === l.id ? ' on' : ''}" data-k="${l.id}">${l.n}</button>`).join('')}</div></section>
  <section class="card lesson"><h2>قصة «${LN[kl]}»</h2><p>${k.story}</p><p class="tip">${k.fact}</p></section>
  <section class="card"><h2>العلماء وصلتهم بالدرس</h2><div class="secs">${k.who.map(([id, role]) => { const s = SCHOLARS[id]; return `<button class="sec" data-s="${id}"><img src="${BOOK_IMAGES[id]}" alt="" loading="lazy" style="height:120px;object-fit:contain" onerror="this.style.display='none'"><span class="st">${s.n}</span><span class="ds">${s.book} · ${s.d}<br>${role}</span></button>`; }).join('')}</div></section>`;
  app.querySelectorAll('[data-k]').forEach(b => b.onclick = () => { kl = b.dataset.k; knowledge(); });
  app.querySelectorAll('[data-s]').forEach(b => b.onclick = () => { const s = SCHOLARS[b.dataset.s]; modal(`<h2>${s.n}</h2><p><em>${s.d}</em> · ${s.city}</p><p>${s.bio}</p>${s.quote ? `<p class="tip">«${s.quote}»</p>` : ''}`); });
}

/* ---------- بدء المحاولة ---------- */
function initState(q) {
  if (q.t === 'mcq') return { v: null, or: shuf(q.o.map((_, n) => n)) };
  if (q.t === 'table') return { c: {}, pk: null, tl: shuf(q.rows.flatMap(r => r.a)) };
  return { p: {}, pk: null, or: shuf(q.p.map((_, n) => n)) };
}
function start() {
  Q = shuf(pl()).slice(0, len).map(q => ({ ...q, st: initState(q) }));
  i = 0; showQ();
}

/* ---------- التصحيح ---------- */
function score(q) {
  const s = q.st;
  if (q.t === 'mcq') return s.v === q.a ? 1 : 0;
  if (q.t === 'table') {
    let ok = 0, tot = 0;
    q.rows.forEach((r, ri) => r.a.forEach((x, ci) => { tot++; const t = s.c[ri + '-' + ci]; if (t !== undefined && s.tl[t] === x) ok++; }));
    return ok / tot;
  }
  return q.p.filter((_, n) => s.p[n] === n).length / q.p.length;
}

/* ---------- عرض السؤال ---------- */
function showQ() {
  const q = Q[i]; locked = false;
  const last = i === Q.length - 1;
  app.innerHTML = `<section class="card">
    <div class="bar"><span>السؤال ${i + 1} من ${Q.length}</span><div><i style="width:${i / Q.length * 100}%"></i></div></div>
    <p class="q">${q.q}</p><div id="body"></div><div id="fb"></div>
    <div class="row"><button class="btn" id="ok">${mode === 'practice' ? 'تحقق' : last ? 'إنهاء' : 'التالي'}</button><button class="btn ghost" id="quit">خروج</button></div></section>`;
  draw();
  $('#ok').onclick = next;
  $('#quit').onclick = () => { if (confirm('هل تريدين الخروج؟ لن تُحفظ هذه المحاولة.')) go('home'); };
}

function next() {
  const q = Q[i];
  if (!locked && !answered(q)) { $('#fb').innerHTML = '<div class="fb no">أجيبي عن السؤال أولًا.</div>'; return; }
  if (mode === 'practice' && !locked) {
    locked = true; q.sc = score(q); draw();
    const f = q.sc === 1;
    $('#fb').innerHTML = `<div class="fb ${f ? 'ok' : 'no'}">${f ? 'أحسنتِ، إجابة صحيحة.' : q.sc > 0 ? 'إجابتك صحيحة جزئيًا. الصحيح موضّح بالألوان.' : 'إجابتك غير صحيحة. الصحيح موضّح بالأخضر.'}${q.e ? '<br>' + q.e : ''}</div>`;
    $('#ok').textContent = i === Q.length - 1 ? 'إنهاء' : 'التالي';
    return;
  }
  q.sc ??= score(q);
  if (++i < Q.length) showQ(); else result();
}

function draw() {
  const q = Q[i], s = q.st, b = $('#body');
  if (q.t === 'mcq') {
    b.innerHTML = s.or.map(n => `<button class="opt${s.v === n ? ' on' : ''}${locked && n === q.a ? ' right' : ''}${locked && s.v === n && n !== q.a ? ' wrong' : ''}" data-n="${n}">${q.o[n]}</button>`).join('');
    b.querySelectorAll('.opt').forEach(x => x.onclick = () => { if (!locked) { s.v = +x.dataset.n; draw(); } });
  } else if (q.t === 'table') {
    const used = new Set(Object.values(s.c));
    b.innerHTML = `<div class="pool">${s.tl.map((t, n) => used.has(n) ? '' : `<button class="tile${s.pk === n ? ' pick' : ''}" data-n="${n}">${t}</button>`).join('')}</div>
    <div class="tw"><table><tr><th></th>${q.cols.map(c => `<th>${c}</th>`).join('')}</tr>
    ${q.rows.map((r, ri) => `<tr><th>${r.s}</th>${q.cols.map((_, ci) => {
      const t = s.c[ri + '-' + ci], has = t !== undefined, good = has && s.tl[t] === r.a[ci];
      const cls = locked ? (good ? 'right' : 'wrong') : '';
      const txt = locked && !good ? (has ? `<s>${s.tl[t]}</s><br>` : '') + `<b>${r.a[ci]}</b>` : (has ? s.tl[t] : '');
      return `<td class="${cls}" data-k="${ri}-${ci}">${txt}</td>`;
    }).join('')}</tr>`).join('')}</table></div>
    ${locked ? '' : '<p class="note">اضغطي على المربع ثم على الخانة المناسبة. للتراجع اضغطي على الخانة.</p>'}`;
    b.querySelectorAll('.tile').forEach(x => x.onclick = () => { if (!locked) { const n = +x.dataset.n; s.pk = s.pk === n ? null : n; draw(); } });
    b.querySelectorAll('td').forEach(x => x.onclick = () => {
      if (locked) return;
      if (s.pk !== null) { s.c[x.dataset.k] = s.pk; s.pk = null; } else delete s.c[x.dataset.k];
      draw();
    });
  } else {
    const owner = r => { const l = Object.keys(s.p).find(l => s.p[l] === r); return l === undefined ? undefined : +l; };
    b.innerHTML = `<div class="mt">${q.p.map((x, k) => {
      const r = s.or[k], l2 = owner(r), paired = s.p[k] !== undefined;
      const lc = locked ? (s.p[k] === k ? ' right' : ' wrong') : (s.pk === k ? ' pk' : '');
      const rc = locked ? (l2 === r ? ' right' : ' wrong') : '';
      return `<button class="${lc.trim()}" data-s="l" data-n="${k}" ${paired && !locked ? `data-c="${k % 4}"` : ''}>${x[0]}${locked && s.p[k] !== k ? `<br><small>← ${x[1]}</small>` : ''}</button>
      <button class="${rc.trim()}" data-s="r" data-n="${r}" ${l2 !== undefined && !locked ? `data-c="${l2 % 4}"` : ''}>${q.p[r][1]}</button>`;
    }).join('')}</div>${locked ? '' : '<p class="note">اضغطي على العنصر من اليمين ثم على ما يناسبه من اليسار. للتراجع اضغطي على الوصلة.</p>'}`;
    b.querySelectorAll('button').forEach(x => x.onclick = () => {
      if (locked) return;
      const n = +x.dataset.n;
      if (x.dataset.s === 'l') { s.pk = s.pk === n ? null : n; }
      else {
        const o = owner(n);
        if (s.pk !== null) { if (o !== undefined) delete s.p[o]; s.p[s.pk] = n; s.pk = null; }
        else if (o !== undefined) delete s.p[o];
      }
      draw();
    });
  }
}

/* ---------- النتيجة وتحليل المهارات ---------- */
const lvl = p => p < 50 ? ['var(--bad)', 'تحتاج إلى مراجعة'] : p < 80 ? ['var(--acc)', 'جيدة وتحتاج إلى مزيد من التدريب'] : ['var(--ok)', 'متقنة'];
function skillsHTML(map) {
  const rows = Object.entries(map).map(([k, [g, t]]) => ({ k, p: Math.round(g / t * 100), t })).sort((a, b) => a.p - b.p);
  return rows.map(r => {
    const [l, sk] = r.k.split('|'), [c, txt] = lvl(r.p);
    return `<div class="sk"><div class="h"><span>${LN[l]} — ${sk}</span><span>${r.p}%</span></div>
      <div class="b"><i style="width:${r.p}%;background:${c}"></i></div>
      <small>${txt}${r.p < 80 ? ' · ' + ((typeof ADVICE !== 'undefined' && ADVICE[r.k] && ADVICE[r.k][r.p < 50 ? 'low' : 'mid']) || `راجعي شرح «${LN[l]}» ثم جرّبي التدريب الفوري.`) : ''}</small></div>`;
  }).join('');
}
function result() {
  const tot = Q.reduce((a, q) => a + q.sc, 0), pct = Math.round(tot / Q.length * 100);
  const sk = {};
  Q.forEach(q => { const k = q.l + '|' + q.k; (sk[k] ??= [0, 0]); sk[k][0] += q.sc; sk[k][1]++; });
  const all = store.get('sk', {});
  for (const k in sk) { const a = all[k] ?? [0, 0]; all[k] = [a[0] + sk[k][0], a[1] + sk[k][1]]; }
  store.set('sk', all);
  store.set('hist', [...store.get('hist', []), { d: new Date().toLocaleDateString('ar-SA'), p: pct, n: Q.length }].slice(-10));
  const msg = pct >= 90 ? 'مستوى ممتاز، واصلي.' : pct >= 70 ? 'مستوى جيد، بقي القليل للإتقان.' : pct >= 50 ? 'بداية جيدة. راجعي المهارات الضعيفة أدناه.' : 'لا بأس، ابدئي بمراجعة الشرح ثم أعيدي المحاولة.';
  app.innerHTML = `<section class="card"><h2>نتيجتك</h2><div class="score">${pct}%</div>
    <p>مجموع درجاتك ${+tot.toFixed(1)} من ${Q.length}. ${msg}</p></section>
    <section class="card"><h2>مهاراتك في هذه المحاولة</h2>${skillsHTML(sk)}</section>
    <section class="card"><h2>مراجعة الأسئلة</h2>${reviewHTML()}</section>
    <div class="row"><button class="btn" id="again">محاولة جديدة</button><button class="btn ghost" id="rv">مراجعة الشرح</button><button class="btn ghost" id="hm">الرئيسية</button></div>`;
  app.querySelectorAll('[data-rv]').forEach(a => a.onclick = e => { e.preventDefault(); const l = LESSONS.find(x => x.id === a.dataset.rv); modal(`<h2>${l.n}</h2>${l.info}<p class="note">المهارة التي تحتاج مراجعة: ${a.dataset.k}</p>`); });
  $('#again').onclick = start; $('#rv').onclick = () => go('learn'); $('#hm').onclick = () => go('home');
}

/* ---------- صفحة مهاراتي ---------- */
const wipe = ks => ks.forEach(k => { try { localStorage.removeItem(k); } catch {} });
function skills() {
  const all = store.get('sk', {}), h = store.get('hist', []), has = Object.keys(all).length;
  app.innerHTML = `<div class="hero sm"><span class="kick">مهاراتي</span><h1>تقييم مهاراتي</h1><p>تُجمع هنا نتائج كل محاولاتك، وتظهر المهارات الأضعف أولًا.</p></div>` +
    (has ? `<section class="card"><h2>تقييم المهارات</h2>${skillsHTML(all)}</section>
      <section class="card"><h2>آخر المحاولات</h2>${h.slice().reverse().map(x => `<p>${x.d} — ${x.p}% في ${x.n} سؤال</p>`).join('')}</section>`
      : `<section class="card"><p>لا توجد نتائج بعد. أكملي اختبارًا أو تدريبًا ليظهر تقييم مهاراتك هنا.</p><div class="row"><button class="btn" data-go="quizzes">ابدئي الآن</button></div></section>`) +
    `<section class="card"><h2>بياناتي</h2>
      <div class="row" style="margin-top:0"><button class="btn ghost" id="c1">مسح التقييمات</button><button class="btn ghost" id="c2">مسح كل سجلّي</button></div>
      <p class="note"><b>مسح التقييمات:</b> يحذف تقييم المهارات فقط، وتبقى قائمة المحاولات.<br><b>مسح كل سجلّي:</b> يحذف التقييمات والمحاولات وإعداداتك (مثل الوضع الليلي)، فيعود الموقع كأنك تدخلينه لأول مرة.</p>
      <p class="note">جميع بياناتك محفوظة على جهازك أنت، داخل هذا المتصفح فقط، ولا تُرسل إلى أي مكان. وإذا مسحتِ بيانات التصفح (ملفات الكوكيز وبيانات المواقع) من المتصفح فستُحذف بيانات هذا الموقع كلها.</p></section>`;
  bindGo(app);
  $('#c1').onclick = () => { if (confirm('سيتم حذف تقييمات المهارات. متأكدة؟')) { wipe(['sk']); skills(); } };
  $('#c2').onclick = () => { if (confirm('سيتم حذف كل بياناتك وكأنك تدخلين الموقع لأول مرة. متأكدة؟')) { wipe(['sk', 'hist', 'th']); sel = new Set(LESSONS.map(l => l.id)); len = 10; theme('dark'); skills(); } };
}


go('home');

/* ---------- مراجعة الإجابات ---------- */
function answered(q) {
  const s = q.st;
  return q.t === 'mcq' ? s.v !== null : Object.keys(q.t === 'table' ? s.c : s.p).length > 0;
}
function ans(q) {
  if (q.t === 'mcq') return q.o[q.a];
  if (q.t === 'table') return q.rows.map(r => r.s + ' ← ' + r.a.join(' | ')).join('<br>');
  return q.p.map(x => x[0] + ' ← ' + x[1]).join('<br>');
}
function reviewHTML() {
  return Q.map((q, n) => {
    const s = q.sc === 1 ? ['ok', 'صحيحة'] : q.sc > 0 ? ['mid', 'جزئية'] : ['no', 'خاطئة'];
    const mine = q.t === 'mcq' && q.sc !== 1 && q.st.v !== null ? `<small>إجابتك: ${q.o[q.st.v]}</small>` : '';
    return `<div class="rv ${s[0]}"><div><b>${n + 1}. ${q.q}</b> <em>${s[1]}</em></div>${mine}${q.sc === 1 ? '' : `<small>الصحيح: ${ans(q)}</small><a href="#" class="rl" data-rv="${q.l}" data-k="${q.k}">راجعي «${LN[q.l]}»</a>`}</div>`;
  }).join('');
}

/* ---------- نافذة منبثقة ---------- */
function modal(html) {
  const m = document.createElement('div'); m.className = 'md';
  m.innerHTML = `<div class="mb" role="dialog" aria-modal="true"><button class="x" aria-label="إغلاق">×</button>${html}</div>`;
  const close = () => { m.remove(); removeEventListener('keydown', esc); }, esc = e => e.key === 'Escape' && close();
  m.onclick = e => { if (e.target === m) close(); };
  m.querySelector('.x').onclick = close; addEventListener('keydown', esc);
  document.body.appendChild(m); m.querySelector('.x').focus();
}

;

